import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{matchingRule,movementResult}from'../core.js';import{matchingPhotographs}from'../photographs.js';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),rules=read('research-updates-20261008.json').filter(x=>['2264.50.00','123.20.35.60.02.001','4832.40.31'].includes(x.baseReference)),photos=read('photographs.json').photographs.filter(x=>x.id.startsWith('omega-22645000-20261026-'));
test('Three exact Omega models keep quartz and Co-Axial movements separate',()=>{assert.equal(rules.length,3);for(const[r,c]of [['22645000','1538'],['12320356002001','1532'],['48324031','2627']])assert.equal(movementResult(matchingRule(rules,'Omega',r),c).level,'match');assert.match(matchingRule(rules,'Omega','12320356002001').technology,/Quartz/);assert.match(matchingRule(rules,'Omega','48324031').technology,/automatic/);assert.equal(movementResult(matchingRule(rules,'Omega','22645000'),'1120').level,'caution');assert.equal(movementResult(matchingRule(rules,'Omega','48324031'),'2628').level,'caution');for(const r of ['22545000','226450','12320352002001','48324032'])assert.equal(matchingRule(rules,'Omega',r),null);});
test('Quartz specimen has three exterior categories without a borrowed movement',()=>{assert.equal(photos.length,3);assert.deepEqual(photos.map(x=>x.category),['front','caseback','braceletClasp']);assert.equal(matchingPhotographs(photos,'Omega','22645000',{externalOnly:true}).length,3);for(const r of ['22545000','12320356002001','48324031'])assert.equal(matchingPhotographs(photos,'Omega',r).length,0);});
